macro.command:
// Arrow of Echoed Wounds
// Fired as ammunition (postActiveEffects of the bow's attack), the arrow's Lodge activity applies Echoed Wound to the creature hit;
// the effect adds 2d6 piercing whenever the target
// takes damage (isDamaged). While it lasts (DAE on/off, on the GM) the target carries a Lodged Arrow item: Pull Out is
// a DC 18 Wisdom (Medicine) check by the wounded creature; a success ends the wound, a failure deals 4d6 piercing.
const FLAG = "echoedWound";
const LODGE = "EchoedWoundLodge", PULL = "LodgedPullOut000", TORN = "LodgedTornWound0";
const name = "Arrow of Echoed Wounds";
const lodged = !!macroItem?.getFlag("midi-qol", "lodgedArrow");

if (args[0] === "on") {
  const macro = macroItem?.flags?.dae?.macro;
  await actor.createEmbeddedDocuments("Item", [{
    name: "Lodged Arrow", type: "feat", img: macroItem?.img ?? "icons/svg/aura.svg",
    system: {
      description: { value: `<p>An arrow of echoed wounds is lodged in you. As an action, you can try to pull it out with a DC 18 Wisdom (Medicine) check: on a success the wound closes; on a failure it tears, dealing 4d6 piercing damage.</p>` },
      activities: {
        [PULL]: { _id: PULL, type: "utility", name: "Pull Out", activation: { type: "action", value: 1 }, target: { affects: { type: "self" } }, range: { units: "self" } },
        [TORN]: { _id: TORN, type: "damage", name: "Torn Wound", activation: { type: "special" }, target: { affects: { type: "self" } }, range: { units: "self" },
          damage: { parts: [{ number: 4, denomination: 6, types: ["piercing"] }] },
          midiProperties: { automationOnly: true, otherActivityCompatible: false, forceConsumeDialog: "never" } }
      }
    },
    flags: { "midi-qol": { lodgedArrow: true, onUseMacroName: "[postActiveEffects]ItemMacro" }, ...(macro ? { dae: { macro } } : {}) }
  }]);
  return;
}
if (args[0] === "off") {
  const ids = actor.items.filter(i => i.getFlag("midi-qol", "lodgedArrow")).map(i => i.id);
  if (ids.length) await actor.deleteEmbeddedDocuments("Item", ids);
  return;
}

if (args[0]?.tag === "OnUse" && args[0].macroPass === "postActiveEffects" && workflow?.ammunition?.id === macroItem?.id) {
  // fired as ammunition: on a hit the arrow lodges (its hidden Lodge activity applies Echoed Wound)
  const target = workflow.hitTargets?.first();
  const lodge = workflow.ammunition.system.activities.get(LODGE);
  if (target && lodge) await MidiQOL.completeActivityUse(lodge, { midiOptions: { targetUuids: [target.document.uuid],
    workflowOptions: { targetConfirmation: "none" } } }, { configure: false }, {});
  return;
}

if (args[0]?.tag === "TargetOnUse" && args[0].macroPass === "isDamaged") {
  // the wounded creature takes damage: the arrow twists
  const di = workflow?.damageItem;
  if (!di || ((di.hpDamage ?? 0) + (di.tempDamage ?? 0)) <= 0) return;
  const roll = await new Roll("2d6[piercing]").evaluate();
  await roll.toMessage({ speaker: ChatMessage.getSpeaker({ actor }), flavor: `${name}: the arrow twists in the wound` });
  MidiQOL.modifyDamageBy({ damageItem: di, value: roll.total, type: "piercing", reason: name });
  return;
}

if (lodged && args[0]?.tag === "OnUse" && args[0].macroPass === "postActiveEffects" && workflow?.activity?.id === PULL) {
  const [check] = await actor.rollSkill({ skill: "med", target: 18 }, {}, {}) ?? [];
  const wound = actor.effects.find(e => e.getFlag("midi-qol", FLAG));
  if ((check?.total ?? 0) >= 18) {
    if (wound) await MidiQOL.socket().executeAsGM("removeEffects", { actorUuid: actor.uuid, effects: [wound.id] });
    return ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor }), content: `<strong>${name}</strong>: the arrow comes free and the wound closes.` });
  }
  await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor }), content: `<strong>${name}</strong>: the arrow tears as it is pulled and stays lodged.` });
  const torn = macroItem.system.activities.get(TORN);
  const me = token?.document?.uuid ?? token?.uuid;
  if (torn && me) await MidiQOL.completeActivityUse(torn, { midiOptions: { targetUuids: [me],
    workflowOptions: { targetConfirmation: "none", autoRollDamage: "always", autoFastDamage: true } } }, { configure: false }, {});
}
